import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import humanTime from 'flarum/common/helpers/humanTime';
import { artStyle } from '../art';
import { category, latest, compact, number, daysAgo } from '../data';
import { t, Sparkline, Stars, UserChip, CategoryLabels, SourceBadge } from './bits';

/**
 * One file in the browse list, as a card (grid) or a row (list).
 *
 * The same facts in both, in the same order: what it is, who made it, how
 * current it is, and how much people use and like it. The grid leads with the
 * picture; the list leads with the words.
 */
export default class FileCard extends Component {
  view() {
    const {
      file,
      mode
    } = this.attrs;
    if (file.locked) return this.locked(file, mode);
    const v = latest(file);
    const fresh = daysAgo(v.date) <= 7;
    const href = app.route('depot.file', {
      slug: file.slug
    });
    if (mode === 'grid') {
      return m(Link, {
        className: "DepotCard",
        href: href
      }, m("div", {
        className: "DepotCard-art",
        style: artStyle(file.art)
      }, m("span", {
        className: "DepotCard-version"
      }, "v", v.version), fresh ? m("span", {
        className: "DepotCard-fresh"
      }, t('card.updated_badge')) : null), m("div", {
        className: "DepotCard-body"
      }, CategoryLabels({
        slug: file.category,
        link: false
      }), m("h3", {
        className: "DepotCard-title"
      }, file.title), m("p", {
        className: "DepotCard-tagline"
      }, file.tagline), m("div", {
        className: "DepotCard-meta"
      }, UserChip({
        user: file.user
      }), m("span", {
        className: "Depot-dim"
      }, humanTime(v.date)))), m("div", {
        className: "DepotCard-foot"
      }, m("span", {
        className: "Depot-metric"
      }, m(Icon, {
        name: "fas fa-download"
      }), " ", m("b", null, compact(file.downloads))), Sparkline({
        values: file.trend,
        width: 64,
        height: 20
      }), m("span", {
        className: "Depot-metric Depot-metric--end"
      }, Stars({
        value: file.rating
      }), " ", m("b", null, file.rating.toFixed(1)))));
    }
    return m(Link, {
      className: "DepotRow",
      href: href
    }, m("div", {
      className: "DepotRow-thumb",
      style: artStyle(file.art)
    }), m("div", {
      className: "DepotRow-main"
    }, m("h3", {
      className: "DepotRow-title"
    }, file.title, " ", m("span", {
      className: "DepotRow-version"
    }, "v", v.version), fresh ? m("span", {
      className: "Depot-pill Depot-pill--fresh"
    }, t('card.updated_badge')) : null, SourceBadge({
      file
    })), m("p", {
      className: "DepotRow-tagline"
    }, file.tagline), m("div", {
      className: "DepotRow-meta"
    }, CategoryLabels({
      slug: file.category,
      link: false
    }), UserChip({
      user: file.user
    }), m("span", {
      className: "Depot-dim"
    }, t('card.updated', {
      time: humanTime(v.date)
    }), " \xB7 ", file.compat[file.compat.length - 1]))), m("div", {
      className: "DepotRow-trend"
    }, Sparkline({
      values: file.trend,
      width: 88,
      height: 26
    }), m("span", {
      className: "Depot-dim"
    }, t('card.last_30_days'))), m("div", {
      className: "DepotRow-stats"
    }, m("span", {
      className: "DepotRow-downloads"
    }, m(Icon, {
      name: "fas fa-download"
    }), " ", number(file.downloads)), m("span", {
      className: "Depot-metric"
    }, Stars({
      value: file.rating
    }), " ", m("span", {
      className: "Depot-dim"
    }, file.rating.toFixed(1)))));
  }

  /**
   * A file this member cannot open, advertised instead of hidden.
   *
   * Built from the title, the count and the group only. The real extension
   * sends a different, smaller shape for these, so there is no picture URL or
   * description in the payload to leak.
   */
  locked(file, mode) {
    const c = category(file.category);
    const body = m("div", {
      className: "DepotLocked-text"
    }, m(Icon, {
      name: "fas fa-lock"
    }), m("b", null, file.title), m("span", {
      className: "Depot-dim"
    }, t('card.locked', {
      count: file.count,
      group: c.group
    })), m("a", {
      className: "Button Button--primary Button--small",
      href: "#",
      onclick: e => e.preventDefault()
    }, t('card.get_access')));
    return m("div", {
      className: `DepotLocked DepotLocked--${mode}`
    }, m("div", {
      className: "DepotLocked-art",
      style: artStyle(file.art)
    }), body);
  }
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/FileCard', FileCard);